import unittest

from hourglass.rounding import round_span_labels
from hourglass.models import Span

class RoundingTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        self.assertEqual(
            round_span_labels([Span(541, 1028)], 15),
            ["09:00-17:15 (8h 15m)"],
        )

    def test_exact_half_rounds_up(self):
        self.assertEqual(
            round_span_labels([Span(555, 1035)], 30),
            ["09:30-17:30 (8h 0m)"],
        )

    def test_whole_day(self):
        self.assertEqual(
            round_span_labels([Span(0, 1440)], 60),
            ["00:00-24:00 (24h 0m)"],
        )

    def test_empty_list(self):
        self.assertEqual(round_span_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 120, 15.0):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_span_labels([Span(0, 60)], step)
